"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type KeyboardEvent,
  type SubmitEvent,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** Props for a feedback widget. Place it with `className`, for example in a fixed corner. */
export type FeedbackWidgetProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "onSubmit"> & {
  /** Sends the message. Throw or reject to show the retry state; the message stays in the field. */
  onSubmit: (message: string) => void | Promise<void>;
  triggerLabel?: string;
  title?: string;
  placeholder?: string;
  /** The line shown after a message sends, before the panel closes itself. */
  thanks?: string;
};

type Phase = "closed" | "open" | "sending" | "sent" | "failed";

const SEND_LABELS = ["Send", "Sending", "Try again"] as const;
const THANKS_MS = 1800;

const POP: Transition = { type: "spring", duration: 0.3, bounce: 0 };
const FADE: Transition = { duration: 0.15 };
const SHOWN = { opacity: 1, scale: 1, filter: "blur(0rem)" };
const DRAW: Transition = { duration: 0.3, ease: [0.215, 0.61, 0.355, 1], delay: 0.1 };

function ChatGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true" className="size-4">
      <path d="M2.5 4.5a2 2 0 0 1 2-2h7a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2H7l-3 2.5v-2.5h0a1.5 1.5 0 0 1-1.5-1.5Z" strokeLinejoin="round" />
    </svg>
  );
}

function CrossGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4">
      <path d="m4.5 4.5 7 7M11.5 4.5l-7 7" strokeLinecap="round" />
    </svg>
  );
}

const QUIET_BUTTON =
  "inline-flex min-h-11 cursor-pointer touch-manipulation items-center justify-center rounded-full px-4 text-sm font-medium outline-none active:scale-97 disabled:cursor-not-allowed disabled:opacity-50 disabled:active:scale-100 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background motion-safe:transition motion-safe:duration-150 sm:min-h-9";

/**
 * A small button that opens into a form for a short message, then confirms
 * the message sent or offers a retry. The panel grows out of the corner the
 * button sat in, so the person sees where it came from.
 */
export function FeedbackWidget({
  onSubmit,
  triggerLabel = "Feedback",
  title = "Send feedback",
  placeholder = "What should we improve?",
  thanks = "Thanks. We read every message.",
  className,
  ...divProps
}: FeedbackWidgetProps) {
  const [phase, setPhase] = useState<Phase>("closed");
  const [message, setMessage] = useState("");
  const reduceMotion = useReducedMotion();
  const titleId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const fieldRef = useRef<HTMLTextAreaElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const returnFocus = useRef(false);
  const draft = message.trim();
  const open = phase !== "closed";
  const sending = phase === "sending";
  // Typed against SEND_LABELS, so a label changed in one place fails the build in the other.
  const sendLabel: (typeof SEND_LABELS)[number] = sending ? "Sending" : phase === "failed" ? "Try again" : "Send";
  const hidden = reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.96, filter: "blur(0.25rem)" };
  const pop = reduceMotion ? FADE : POP;

  useEffect(() => {
    if (phase === "open") fieldRef.current?.focus();
    // The field leaves with the thank-you view, so the panel itself takes focus instead of the page.
    if (phase === "sent") panelRef.current?.focus();
    if (phase === "closed" && returnFocus.current) {
      returnFocus.current = false;
      triggerRef.current?.focus();
    }
    // The thank-you closes itself. Leaving that view first cancels the timer, so it never closes a reopened panel.
    if (phase !== "sent") return;
    const timer = window.setTimeout(() => {
      returnFocus.current = true;
      setPhase("closed");
    }, THANKS_MS);
    return () => window.clearTimeout(timer);
  }, [phase]);

  // A press outside closes the panel and keeps the draft, unless a message is on its way.
  useEffect(() => {
    if (phase === "closed" || phase === "sending") return;
    const onPointerDown = (event: PointerEvent) => {
      if (event.target instanceof Node && !rootRef.current?.contains(event.target)) setPhase("closed");
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [phase]);

  const close = () => {
    if (sending) return;
    returnFocus.current = true;
    setPhase("closed");
  };

  const send = async (event?: SubmitEvent<HTMLFormElement>) => {
    event?.preventDefault();
    if (sending || draft === "") return;
    setPhase("sending");
    try {
      await onSubmit(draft);
      setMessage("");
      setPhase("sent");
    } catch {
      setPhase("failed");
    }
  };

  // Escape is heard on the panel only, so it never closes this panel while another widget has focus.
  // Cmd or Ctrl with Enter sends, so a person who types fast never reaches for the pointer.
  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") {
      event.preventDefault();
      close();
    }
    if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) void send();
  };

  return (
    <div {...divProps} ref={rootRef} className={cn("relative inline-flex", className)}>
      {/* The button stays mounted under the panel, so the panel always grows from the same corner and focus has somewhere to return. */}
      <motion.button
        ref={triggerRef}
        type="button"
        aria-haspopup="dialog"
        aria-expanded={open}
        inert={open}
        onClick={() => setPhase("open")}
        initial={false}
        animate={open ? hidden : SHOWN}
        transition={pop}
        className={cn(QUIET_BUTTON, "origin-bottom-right gap-2 border border-border bg-background text-foreground shadow-sm hover:bg-muted")}
      >
        <ChatGlyph />
        {triggerLabel}
      </motion.button>
      <AnimatePresence initial={false}>
        {open ? (
          <motion.div
            key="panel"
            ref={panelRef}
            tabIndex={-1}
            role="dialog"
            aria-label={title}
            onKeyDown={handleKeyDown}
            initial={hidden}
            animate={SHOWN}
            exit={hidden}
            transition={pop}
            className="absolute bottom-0 right-0 z-10 w-64 max-w-[calc(100vw-2rem)] origin-bottom-right sm:w-72 rounded-2xl border border-border bg-background p-4 shadow-lg outline-none"
          >
            {phase === "sent" ? (
              <div className="flex flex-col items-center gap-3 py-4 text-center">
                <span className="grid size-10 place-items-center rounded-full bg-primary text-primary-foreground">
                  <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-5">
                    <motion.path
                      d="m3 8.5 3.25 3.25L13 5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      initial={{ pathLength: reduceMotion ? 1 : 0 }}
                      animate={{ pathLength: 1 }}
                      transition={DRAW}
                    />
                  </svg>
                </span>
                <p className="text-sm font-medium text-foreground">{thanks}</p>
              </div>
            ) : (
              <form onSubmit={send}>
                <div className="flex items-center justify-between gap-3">
                  <p id={titleId} className="text-sm font-semibold text-foreground">
                    {title}
                  </p>
                  <button
                    type="button"
                    aria-label="Close"
                    onClick={close}
                    disabled={sending}
                    className="grid size-11 cursor-pointer place-items-center rounded-full text-muted-foreground outline-none hover:bg-muted hover:text-foreground disabled:cursor-not-allowed disabled:opacity-50 focus-visible:ring-2 focus-visible:ring-ring sm:size-8"
                  >
                    <CrossGlyph />
                  </button>
                </div>
                <textarea
                  ref={fieldRef}
                  aria-labelledby={titleId}
                  value={message}
                  onChange={(event) => setMessage(event.target.value)}
                  readOnly={sending}
                  placeholder={placeholder}
                  rows={3}
                  // The panel's radius minus its padding is zero, so the field takes the smallest radius and
                  // nests inside the curve whatever the theme's --radius is.
                  className="mt-3 w-full resize-none rounded-xs border border-border bg-background px-3.5 py-3 text-base text-foreground outline-none placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring sm:text-sm"
                />
                {phase === "failed" ? (
                  <p role="alert" className="mt-2 text-sm text-destructive">
                    Your message did not send. Try again.
                  </p>
                ) : null}
                <div className="mt-3 flex justify-end gap-2">
                  <button type="button" onClick={close} disabled={sending} className={cn(QUIET_BUTTON, "text-foreground hover:bg-muted")}>
                    Cancel
                  </button>
                  <button
                    type="submit"
                    // While it sends, the button stays focusable, so a keyboard user keeps their place.
                    disabled={!sending && draft === ""}
                    aria-disabled={sending || undefined}
                    aria-label={sendLabel}
                    className={cn(QUIET_BUTTON, "bg-primary text-primary-foreground", sending && "cursor-progress")}
                  >
                    {/* Every label sits in one grid cell, so the button keeps the width of the longest. */}
                    <span aria-hidden="true" className="grid">
                      {SEND_LABELS.map((label) => (
                        <motion.span
                          key={label}
                          initial={false}
                          animate={{ opacity: label === sendLabel ? 1 : 0 }}
                          transition={FADE}
                          className="col-start-1 row-start-1 whitespace-nowrap"
                        >
                          {label}
                        </motion.span>
                      ))}
                    </span>
                  </button>
                </div>
              </form>
            )}
          </motion.div>
        ) : null}
      </AnimatePresence>
      {/* The live region stays mounted, so a screen reader hears each change of state. */}
      <span role="status" className="sr-only">
        {sending ? "Sending" : phase === "sent" ? thanks : ""}
      </span>
    </div>
  );
}
